import pandas as pd,numpy as np
from scipy.stats import pearsonr,spearmanr
s=pd.read_csv('dataset/stations.csv').set_index('station_id'); r=pd.read_csv('dataset/readings.csv'); r.timestamp=pd.to_datetime(r.timestamp)
ws=pd.read_csv('dataset/weather_stations.csv').set_index('weather_station_id'); w=pd.read_csv('dataset/weather_readings.csv'); w.timestamp=pd.to_datetime(w.timestamp)
t=sorted(r.timestamp.unique()); M=r.pivot(index='station_id',columns='timestamp',values='current_reading').reindex(columns=t); Mi=M.T.interpolate(limit=2,limit_area='inside').T
pol=r.groupby('station_id').pollutant.first(); xy=s[['latitude','longitude']]*[111,70]; wxy=ws[['latitude','longitude']]*[111,70]
V=['temperature_c','humidity_pct','wind_speed_m_s','rain_accumulation_mm']; WM={v:w.pivot(index='weather_station_id',columns='timestamp',values=v).reindex(columns=t) for v in V}
for method in ['diff','ols']:
 rows=[]
 for st in M.index:
  peers=M.index[(pol==pol[st]) & (s.district==s.loc[st,'district']) & (M.index!=st)]
  base=Mi.loc[peers].median(axis=0).values
  y=M.loc[st].values # observed only target
  q=np.isfinite(y)&np.isfinite(base)
  if method=='ols':
   X=np.c_[np.ones(q.sum()),base[q]]; co=np.linalg.lstsq(X,y[q],rcond=None)[0]; e=y-co[0]-co[1]*base
  else:e=y-base-np.nanmean(y-base)
  wd=np.sqrt(((wxy-xy.loc[st])**2).sum(axis=1)).sort_values()
  vals=[]
  for v in V:
   wvs={
    'near':WM[v].loc[wd.index[0]].values,
    'near3':WM[v].loc[wd.index[:3]].median(axis=0).values,
    'dist':WM[v].loc[ws.index[ws.district==s.loc[st,'district']]].median(axis=0).values}
   for typ,wv in wvs.items():
    qq=np.isfinite(e); pr=pearsonr(e[qq],wv[qq])[0]; sr=spearmanr(e[qq],wv[qq])[0]
    vals.append((abs(pr),pr,v,typ,abs(sr)))
  best=max(vals)
  rows.append([st,pol[st],s.loc[st,'district'],len(peers),q.sum(),*best])
 z=pd.DataFrame(rows,columns=['st','pol','district','npeer','obs','absr','r','var','wtype','abss'])
 print('\n',method,'best overall observed only')
 print(z.sort_values('absr',ascending=False).head(30).to_string(index=False,float_format=lambda x:f'{x:.3f}'))
 # each variable using district median only
 for v in V:
  zz=[]
  for st in M.index:
   peers=M.index[(pol==pol[st]) & (s.district==s.loc[st,'district']) & (M.index!=st)]
   base=Mi.loc[peers].median(axis=0).values; y=M.loc[st].values; q=np.isfinite(y)&np.isfinite(base)
   if method=='ols':
    co=np.linalg.lstsq(np.c_[np.ones(q.sum()),base[q]],y[q],rcond=None)[0]; e=y-co[0]-co[1]*base
   else:e=y-base-np.nanmean(y-base)
   wv=WM[v].loc[ws.index[ws.district==s.loc[st,'district']]].median(axis=0).values
   zz.append((st,pearsonr(e[q],wv[q])[0],spearmanr(e[q],wv[q])[0]))
  print(v, sorted(zz,key=lambda x:abs(x[1]),reverse=True)[:8])
